(6634487, 991101, 94265, '<td valign="top">This looks to me like you''ve either majorly bumped the midtones and highlights to create a high-key effect causing the noise to be really visible on the crow, or you deliberately took the shot this way by bumping the ISO up loads to create the same effect (and caused the heavy noise.) It doesn''t work for me either way, shame as the composition is good and I like the subject.</td>', 'This looks to me like you''ve either majorly bumped the midtones and highlights to create a high-key effect causing the noise to be really visible on the crow, or you deliberately took the shot this way by bumping the ISO up loads to create the same effect (and caused the heavy noise.) It doesn''t work for me either way, shame as the composition is good and I like the subject.', '2012-01-04 11:58:06.000000', NULL, 1),
(6634489, 990814, 73942, '<td valign="top">beautiful</td>', 'beautiful', '2012-01-04 11:58:30.000000', NULL, 1),
