(6634491, 991056, 94265, '<td valign="top">Very beautiful bird, nice focus on it. I''d have perhaps cropped in a bit closer to the bird, as the surrounding bare branches aren''t particularly interesting. Good capture overall.</td>', 'Very beautiful bird, nice focus on it. I''d have perhaps cropped in a bit closer to the bird, as the surrounding bare branches aren''t particularly interesting. Good capture overall.', '2012-01-04 12:00:25.000000', NULL, 1),
(6634492, 990902, 94265, '<td valign="top">Made me chuckle, good angle, I like the muted colours. Processing has made the image look a bit soft though. How did you get the blue ribbon on there, surely you didn''t graffiti somebody''s headstone?</td>', 'Made me chuckle, good angle, I like the muted colours. Processing has made the image look a bit soft though. How did you get the blue ribbon on there, surely you didn''t graffiti somebody''s headstone?', '2012-01-04 12:03:18.000000', NULL, 1),
(6634493, 990316, 94265, '<td valign="top">I like the idea, it does suit the username. Lighting is a bit flat though and I don''t personally like the selective blur.</td>', 'I like the idea, it does suit the username. Lighting is a bit flat though and I don''t personally like the selective blur.', '2012-01-04 12:04:38.000000', NULL, 1),
