(6637721, 990778, 62249, '<td valign="top">Very nice. I like the tonal range in this and the subtle color palette.</td>', 'Very nice. I like the tonal range in this and the subtle color palette.', '2012-01-07 14:00:41.000000', NULL, 1),
(6637722, 990993, 142473, '<td valign="top">Lots of emotion in the angle you captured this.  Not exactly what most people would have thought of when they were looking for the theme of "backlight", but I think that''s why it works.</td>', 'Lots of emotion in the angle you captured this.  Not exactly what most people would have thought of when they were looking for the theme of "backlight", but I think that''s why it works.', '2012-01-07 14:00:58.000000', NULL, 1),
