(6637725, 990316, 62249, '<td valign="top">Would''ve been nice to see more separation between the black phone and the man''s jacket. But the image tells a story, which is good.</td>', 'Would''ve been nice to see more separation between the black phone and the man''s jacket. But the image tells a story, which is good.', '2012-01-07 14:03:02.000000', NULL, 1),
(6637726, 990173, 62249, '<td valign="top">Love the bird in flight at the right edge of the photo.</td>', 'Love the bird in flight at the right edge of the photo.', '2012-01-07 14:04:10.000000', NULL, 1),
(6637728, 990715, 62249, '<td valign="top">I like the idea behind this shot, but the composition isn''t very strong. Too many elements to look at, and they''re not arranged in a way that successfully leads a viewer''s eye through the image.</td>', 'I like the idea behind this shot, but the composition isn''t very strong. Too many elements to look at, and they''re not arranged in a way that successfully leads a viewer''s eye through the image.', '2012-01-07 14:10:48.000000', NULL, 1),
